create function pg_temp.assert_true(v boolean,msg text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'ASSERT: %',msg;end if;end$$;
create function pg_temp.expect_error(sql text,expected text) returns void language plpgsql as $$begin begin execute sql;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected rejection: %',expected;end$$;
select id as clinic from public.clinics where name='Synthetic medication permissions' \gset
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000150',false);set role authenticated;
select public.ops_week_plan_commit(:'clinic','2026-11-02','','Plan revisado','[{"title": "Preparar recepci\u00f3n", "scheduled_on": "2026-11-02", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000151"}, {"title": "Ordenar materiales", "scheduled_on": "2026-11-03", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000152"}]'::jsonb,(md5('batch-a')||left(md5('batch-a'),16))) as batch \gset
select public.ops_week_plan_commit(:'clinic','2026-11-02','','Plan revisado','[{"title": "Preparar recepci\u00f3n", "scheduled_on": "2026-11-02", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000151"}, {"title": "Ordenar materiales", "scheduled_on": "2026-11-03", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000152"}]'::jsonb,(md5('batch-a')||left(md5('batch-a'),16)));
select public.ops_week_plan_commit(:'clinic','2026-11-02','','Plan revisado','[{"title": "Ordenar materiales", "scheduled_on": "2026-11-03", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000152"}, {"title": "Preparar recepci\u00f3n", "scheduled_on": "2026-11-02", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000151"}]'::jsonb,(md5('batch-b')||left(md5('batch-b'),16)));
select pg_temp.assert_true(jsonb_array_length(public.ops_productivity_read(:'clinic','2026-11-02')->'tasks')=2,'retry duplicated tasks');
select pg_temp.expect_error(format('select public.ops_week_plan_commit(%L,''2026-11-02'','''',''Cambio'',''[{"title": "Otro", "scheduled_on": "2026-11-02", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000151"}]''::jsonb,(md5(''batch-c'')||left(md5(''batch-c''),16)))',:'clinic'),'week_plan_changed_refresh');
select pg_temp.expect_error(format('select public.ops_week_plan_commit(%L,''2026-11-02'',''Plan revisado'',''Cambio'',''[{"title": "Extra A", "scheduled_on": "2026-11-02", "estimated_minutes": 10, "assigned_to": "00000000-0000-0000-0000-000000000151"}, {"title": "Extra B", "scheduled_on": "2026-11-02", "estimated_minutes": 10, "assigned_to": "00000000-0000-0000-0000-000000000151"}]''::jsonb,(md5(''batch-d'')||left(md5(''batch-d''),16)))',:'clinic'),'daily_task_capacity_exceeded');
select pg_temp.expect_error(format('select public.ops_week_plan_commit(%L,''2026-11-02'',''Plan revisado'',''Cambio'',''[{"title": "Mi\u00e9rcoles", "scheduled_on": "2026-11-04", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000151"}]''::jsonb,(md5(''batch-e'')||left(md5(''batch-e''),16)))',:'clinic'),'assignee_unavailable');
select pg_temp.expect_error(format('select public.ops_week_plan_commit(%L,''2026-11-02'',''Plan revisado'',''Cambio'',''[{"title": "Ajeno", "scheduled_on": "2026-11-02", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000154"}]''::jsonb,(md5(''batch-f'')||left(md5(''batch-f''),16)))',:'clinic'),'assignee_wrong_clinic');
select pg_temp.assert_true(public.ops_productivity_read(:'clinic','2026-11-02')->>'plan'='Plan revisado','failed batch changed plan');
select pg_temp.assert_true(jsonb_array_length(public.ops_productivity_read(:'clinic','2026-11-02')->'tasks')=2,'failed batch left partial tasks');
select pg_temp.expect_error(format('select public.ops_week_plan_commit(%L,%L,%L,%L,%L::jsonb,%L)',:'clinic','2026-11-02','Plan revisado','Cambio','[{"title":"Preparar recepción","scheduled_on":"2026-11-02","estimated_minutes":5,"assigned_to":"00000000-0000-0000-0000-000000000151"}]',(md5('batch-duplicate')||left(md5('batch-duplicate'),16))),'task_already_scheduled');
select pg_temp.expect_error(format('select public.ops_week_plan_commit(%L,%L,%L,%L,%L::jsonb,%L)',:'clinic','2026-11-02','Plan revisado','Cambio','[{"title":"Fuera de semana","scheduled_on":"2026-11-09","estimated_minutes":5}]',(md5('batch-week')||left(md5('batch-week'),16))),'task_week_or_duration_invalid');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000151',false);set role authenticated;
select pg_temp.expect_error(format('select public.ops_week_plan_commit(%L,''2026-11-02'',''Plan revisado'',''Cambio'',''[{"title": "Preparar recepci\u00f3n", "scheduled_on": "2026-11-02", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000151"}, {"title": "Ordenar materiales", "scheduled_on": "2026-11-03", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000152"}]''::jsonb,(md5(''batch-g'')||left(md5(''batch-g''),16)))',:'clinic'),'team_manage_required');
reset role;set role anon;
select pg_temp.expect_error(format('select public.ops_week_plan_commit(%L,''2026-11-02'',''Plan revisado'',''Cambio'',''[{"title": "Preparar recepci\u00f3n", "scheduled_on": "2026-11-02", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000151"}, {"title": "Ordenar materiales", "scheduled_on": "2026-11-03", "estimated_minutes": 15, "assigned_to": "00000000-0000-0000-0000-000000000152"}]''::jsonb,(md5(''batch-h'')||left(md5(''batch-h''),16)))',:'clinic'),'permission denied');
reset role;
